def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The unique 9 marks the center of the pattern; its cardinal neighbors
    # specify the colors to stamp around each zero.
    centers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 9]
    if not centers:
        return out
    r0, c0 = centers[0]
    offsets = [(0, 0), (-1, 0), (1, 0), (0, -1), (0, 1)]
    pattern = []
    for dr, dc in offsets:
        rr, cc = r0 + dr, c0 + dc
        if 0 <= rr < h and 0 <= cc < w:
            pattern.append((dr, dc, grid[rr][cc]))

    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    for r, c in anchors:
        for dr, dc, color in pattern:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
